import fitz
d = fitz.open('eprint/Main-text/figure-3-6.pdf')
p = d[0]
drawings = p.get_drawings()
def seg(dr):
    out=[]
    for it in dr['items']:
        if it[0]=='l': out.append((it[1].x,it[1].y,it[2].x,it[2].y))
        else: out.append((it[0],))
    return out
# bottom axis of panel b: find stroke drawing with rect y~171.75 spanning x 139-340
for i,dr in enumerate(drawings):
    r=dr['rect']
    if dr['type']=='s' and abs(r.y0-171.75)<0.5 and r.x0>135 and r.width>150:
        segs=seg(dr)
        vt=[round(s[0],2) for s in segs if len(s)==4 and abs(s[0]-s[2])<0.01 and abs(s[1]-s[3])>1.0]
        print(i,'bottom ticks x:',sorted(set(vt)))
    if dr['type']=='s' and abs(r.x0-138.91)<0.3 and r.height>100:
        segs=seg(dr)
        ht=[round(s[1],2) for s in segs if len(s)==4 and abs(s[1]-s[3])<0.01 and abs(s[0]-s[2])>1.0]
        print(i,'left ticks y:',sorted(set(ht)))
EOF

