import numpy as np
b = np.load('boundary.npy')
def mass(x): return 10**(-15 + (x-155.36)/42.88)
def eps(y): return 10**(-(y-22.201)/13.4763)
sel = b[:,0]<188
lb = np.unique(b[sel], axis=0)
lb = lb[np.argsort(lb[:,0])]
for x,y in lb: print(f"{x:.2f} {y:.2f}  m={mass(x):.3e} eps={eps(y):.3e}")
EOF
